// Umbrales clínicos configurables
const sv = $input.item.json.body;
const alertas = [];

// Glucosa (mg/dL)
if (sv.glucosa !== undefined) {
  if (sv.glucosa > 250) alertas.push({ tipo: 'Glucosa', valor: sv.glucosa, umbral: '>250 mg/dL', severidad: 'CRÍTICO' });
  else if (sv.glucosa > 180) alertas.push({ tipo: 'Glucosa', valor: sv.glucosa, umbral: '>180 mg/dL', severidad: 'ALTO' });
  else if (sv.glucosa < 70) alertas.push({ tipo: 'Glucosa', valor: sv.glucosa, umbral: '<70 mg/dL (HIPOGLUCEMIA)', severidad: 'CRÍTICO' });
}

// Presión sistólica (mmHg)
if (sv.presionSistolica !== undefined) {
  if (sv.presionSistolica > 180) alertas.push({ tipo: 'Presión Sistólica', valor: sv.presionSistolica, umbral: '>180 mmHg', severidad: 'CRÍTICO' });
  else if (sv.presionSistolica > 140) alertas.push({ tipo: 'Presión Sistólica', valor: sv.presionSistolica, umbral: '>140 mmHg', severidad: 'ALTO' });
  else if (sv.presionSistolica < 90) alertas.push({ tipo: 'Presión Sistólica', valor: sv.presionSistolica, umbral: '<90 mmHg', severidad: 'CRÍTICO' });
}

// Frecuencia cardíaca (bpm)
if (sv.frecuenciaCardiaca !== undefined) {
  if (sv.frecuenciaCardiaca > 120) alertas.push({ tipo: 'Frecuencia Cardíaca', valor: sv.frecuenciaCardiaca, umbral: '>120 bpm', severidad: 'CRÍTICO' });
  else if (sv.frecuenciaCardiaca < 50) alertas.push({ tipo: 'Frecuencia Cardíaca', valor: sv.frecuenciaCardiaca, umbral: '<50 bpm', severidad: 'CRÍTICO' });
}

// Saturación O2 (%)
if (sv.saturacionO2 !== undefined) {
  if (sv.saturacionO2 < 90) alertas.push({ tipo: 'Saturación O2', valor: sv.saturacionO2, umbral: '<90%', severidad: 'CRÍTICO' });
  else if (sv.saturacionO2 < 95) alertas.push({ tipo: 'Saturación O2', valor: sv.saturacionO2, umbral: '<95%', severidad: 'ALTO' });
}

// Temperatura (°C)
if (sv.temperatura !== undefined) {
  if (sv.temperatura > 39.5) alertas.push({ tipo: 'Temperatura', valor: sv.temperatura, umbral: '>39.5°C', severidad: 'CRÍTICO' });
  else if (sv.temperatura > 38) alertas.push({ tipo: 'Temperatura', valor: sv.temperatura, umbral: '>38°C (Fiebre)', severidad: 'ALTO' });
  else if (sv.temperatura < 36) alertas.push({ tipo: 'Temperatura', valor: sv.temperatura, umbral: '<36°C (Hipotermia)', severidad: 'ALTO' });
}

return [{ 
  json: { 
    alertas,
    hayAlertas: alertas.length > 0,
    hayAlertasCriticas: alertas.some(a => a.severidad === 'CRÍTICO'),
    pacienteId: sv.pacienteId,
    pacienteNombre: sv.pacienteNombre,
    medicoEmail: sv.medicoEmail,
    timestamp: new Date().toISOString(),
    signosVitales: sv
  } 
}];
